#include <iostream>
#include <span>
#include <string>
#include <string_view>
#include <variant>
#include <vector>
struct Error {};
std::variant<int, Error> parse(std::string_view s) {
    if (s == "42") return 42;
    return Error{};
}
int main() {
    std::vector<int> a{10, 20, 30};
    std::span<const int> v(a.data(), 2);
    std::string owner = "ABCXYZ";
    std::cout << v[0]+v[1] << '\n';
    std::cout << std::string_view(owner).substr(0, 3) << '\n';
    std::cout << std::holds_alternative<Error>(parse("bad")) << '\n';
}

